mapper.update:
update job
company_id = #{companyId}, category_id = #{categoryId}, title = #{title}, description = #{description}, requirement = #{requirement}, salary_min = #{salaryMin}, salary_max = #{salaryMax}, city = #{city}, education = #{education}, tags = #{tags}, status = #{status}, deadline = #{deadline}, update_time = #{updateTime}, update_user = #{updateUser}
where id = #{id}

mapper.select:
select j.*, c.name companyName, k.name categoryName
from job j
left join company c on j.company_id = c.id
left join job_category k on j.category_id = k.id

    and j.title like concat('%', #{title}, '%')
    and j.category_id = #{categoryId}
    and j.status = #{status}


        and j.city like concat('%', #{city}, '%')

    and j.company_id = #{companyId}

order by j.create_time desc
